@@ -3,7 +3,7 @@ import { fetchItems, saveItem } from "./store.js";
 /** Items that carry `tag`. */
 export async function findByTag(tag) {
   const items = await fetchItems();
-  return items.filter((item) => item.tags[0] === tag);
